// Sample toggling two components, triggering lifecycle transitions
class MainPage : Component<MainPageState>
{
    public override VisualNode Render() => new ContentPage
    {
        new VStack
        {
            new Button($"Use {( !State.Toggle ? "increment" : "decrement" )} button", () => SetState(s => s.Toggle = !s.Toggle)),
            State.Toggle ?
                new IncrementalCounter().CurrentValue(State.CurrentValue).ValueChanged(v => SetState(s => s.CurrentValue = v)) :
                new DecrementalCounter().CurrentValue(State.CurrentValue).ValueChanged(v => SetState(s => s.CurrentValue = v))
        }
        .Center()
    };
}
